import React from 'react';

const QuestionCard = ({ index, qa, questions, hideAnswers, onChange }) => {
  const isMismatch = qa.confirmAnswer && qa.answer !== qa.confirmAnswer;

  return (
    <div className="question-block">
      <label className="question-label">Question {index + 1}</label>
      
      <select
        className="form-select"
        value={qa.question}
        onChange={e => onChange(index, 'question', e.target.value)}
      >
        <option value="">-- Choose a question --</option>
        {questions.map((q, i) => (
          <option key={i} value={typeof q === 'object' ? q.text : q}>
            {typeof q === 'object' ? q.text : q}
          </option>
        ))}
      </select>

      <div className="input-row">
        <div className="input-group">
          <input
            className="form-input"
            type={hideAnswers ? "password" : "text"}
            placeholder="Answer"
            value={qa.answer}
            onChange={e => onChange(index, 'answer', e.target.value)}
          />
        </div>
        
        <div className="input-group">
          <input
            className={`form-input ${isMismatch ? 'input-error' : ''}`}
            type={hideAnswers ? "password" : "text"}
            placeholder="Confirm Answer"
            value={qa.confirmAnswer}
            onChange={e => onChange(index, 'confirmAnswer', e.target.value)}
          />
        </div>
      </div>
      
      {isMismatch && <span className="error-text">* Answers do not match</span>}
    </div>
  );
};

export default QuestionCard;
